struct boss_brawguild_masterAI : public BrawlersBossAI
    {
        boss_brawguild_masterAI(Creature* creature) : BrawlersBossAI(creature)
        {
            count_adds = 0;
            me->setRegeneratingHealth(false);
            me->SetReactState(REACT_PASSIVE);
        }

        uint8 count_adds;
        uint8 phase_of_sphere;
        uint32 timer_check;
        std::set<ObjectGuid> activeAddGuids;

        void Reset() override
        {
            me->KillAllDelayedEvents();
            _Reset();
            activeAddGuids.clear();
            count_adds = 0;
            phase_of_sphere = 0;
            timer_check = 500;
            if (me->GetEntry() == 115645)
            {
                me->CastSpell(me, 229862);
                me->SummonCreature(115637,  me->GetPositionX() , me->GetPositionY(), me->GetPositionZ(), me->GetOrientation());
                me->SummonCreature(115637,  me->GetPositionX() , me->GetPositionY(), me->GetPositionZ(), me->GetOrientation());
                me->SummonCreature(115637,  me->GetPositionX() , me->GetPositionY(), me->GetPositionZ(), me->GetOrientation());

                if (me->GetAnyOwner() && me->GetAnyOwner()->IsPlayer())
                {
                    if (Player* player = me->GetAnyOwner()->ToPlayer())
                    {
                        Position* pos = player->GetTeamId() == TEAM_ALLIANCE ? a_atPos : h_atPos;
                        uint8 count = player->GetTeamId() == TEAM_ALLIANCE ? 42 : 93;
                        for (uint8 i = 0; i < count; ++i)
                            me->CreateAreaTrigger(4520, pos[i].GetPositionX() , pos[i].GetPositionY(), pos[i].GetPositionZ(), pos[i].GetOrientation());
                    }
                }
                phase_of_sphere = 1;

                me->AddDelayedEvent(3000, [this] () -> void
                {
                    if (me->GetAnyOwner() && me->GetAnyOwner()->IsPlayer())
                    {
                        if (Player* player = me->GetAnyOwner()->ToPlayer())
                        {
                            Position* pos = player->GetTeamId() == TEAM_ALLIANCE ? a_spherePos : h_spherePos;
                            for (uint8 i = 0; i < 5; ++i)
                                me->SummonCreature(115660, pos[i].GetPositionX(), pos[i].GetPositionY(), pos[i].GetPositionZ(), pos[i].GetOrientation());
                        }
                    }
                });

                if (Unit* owner = me->GetAnyOwner())
                    if (Player* player = owner->ToPlayer())
                        player->AddAura(SPELL_MOVE_FORWARD, player);
                me->SetVisible(false);
            }
        }

        void EnterEvadeMode() override {}

        void LastWPReached() override
        {
            me->GetMotionMaster()->Clear();

            if (Unit* owner = me->GetAnyOwner())
                if(Creature* creature = owner->ToCreature())
                    if (Unit* ownerCreature = creature->GetAnyOwner())
                        if (Player* player = ownerCreature->ToPlayer())
                            me->GetMotionMaster()->MovePath(player->GetTeamId() == TEAM_ALLIANCE ? a_WP[urand(0, 4)] :  h_WP[urand(0, 4)], false);
        }

        void DoAction(int32 const action) override
        {
            if (me->GetEntry() == 115645)
            {
                summons.DespawnEntry(115660);
                EntryCheckPredicate pred(115637);
                summons.DoAction(true, pred);

                me->AddDelayedEvent(20000, [this] () -> void
                {
                    if (me->GetAnyOwner() && me->GetAnyOwner()->IsPlayer())
                    {
                        if (Player* player = me->GetAnyOwner()->ToPlayer())
                        {
                            Position* pos = player->GetTeamId() == TEAM_ALLIANCE ? a_spherePos : h_spherePos;
                            for (uint8 i = phase_of_sphere*5; i < phase_of_sphere*5 + 5; ++i)
                                me->SummonCreature(115660, pos[i].GetPositionX(), pos[i].GetPositionY(), pos[i].GetPositionZ(), pos[i].GetOrientation());
                        }
                    }
                });

                phase_of_sphere++;

                if (phase_of_sphere == 3)
                    phase_of_sphere = 0;
            }
            else if (me->GetEntry() == 115637)
                DoCast(SPELL_DZEN);
        }

        void JustSummoned(Creature* summon) override
        {
            summons.Summon(summon);

            if (summon->GetEntry() != 115637 || count_adds >= 3 || !activeAddGuids.insert(summon->GetGUID()).second)
                return;

            if (Unit* owner = me->GetAnyOwner())
                summon->AI()->EnterCombat(owner); // some hack

            if (me->GetAnyOwner() && me->GetAnyOwner()->IsPlayer())
                if (Player* player = me->GetAnyOwner()->ToPlayer())
                {
                    summon->GetMotionMaster()->MovePath(player->GetTeamId() == TEAM_ALLIANCE ? a_WP[count_adds] :  h_WP[count_adds], false);
                    summon->AddDelayedEvent(47000, [summon, team = player->GetTeamId()] () -> void
                    {
                        summon->GetMotionMaster()->Clear();
                        summon->GetMotionMaster()->MovePath(team == TEAM_ALLIANCE ? a_WP[urand(0, 5)] : h_WP[urand(0, 5)], false);
                    });
                }

            count_adds++;

            switch(count_adds)
            {
                case 1:
                    summon->CastSpell(summon, 229861);
                    summon->CastSpell(summon, SPELL_MAIN_STATE);
                    break;
                case 2:
                    summon->CastSpell(summon, 229860);
                    summon->CastSpell(summon, SPELL_MAIN_STATE);
                    break;
                case 3:
                    summon->CastSpell(summon, 229852);
                    summon->CastSpell(summon, SPELL_MAIN_STATE);
                    break;
            }
        }

        void JustDied(Unit* who) override
        {
            if (me->GetEntry() == 115637)
            {
                me->DespawnOrUnsummon(100);
                return;
            }

			_Reset();
            me->KillAllDelayedEvents();

            if (!who)
                return;

           _WinRound();
        }

        void KilledUnit(Unit* who) override
        {
            if (Unit* owner = me->GetAnyOwner())
            {
                if (owner->IsPlayer())
                {
                    if (who->GetGUID() != owner->GetGUID())
                        return;
                    me->KillAllDelayedEvents();
                    _Reset();
                    _LoseRound();
                }
                else
                    owner->ToCreature()->AI()->KilledUnit(who); // i know, that it so crazy =C
            }
        }

        void SummonedCreatureDies(Creature* summon, Unit* /*killer*/) override
        {
            if (summon->GetEntry() != 115637 || activeAddGuids.erase(summon->GetGUID()) != 1)
                return;

            count_adds--;
            if (count_adds == 0)
            {
                summons.DespawnAll();
                me->RemoveAllAreaObjects();
                if (me->GetAnyOwner() && me->GetAnyOwner()->IsPlayer())
                {
                    me->KillAllDelayedEvents();
                    Player* player = me->GetAnyOwner()->ToPlayer();
                    me->AddDelayedEvent(700, [this, playerGuid = player->GetGUID()] () -> void
                    {
                        if (Player* player = ObjectAccessor::GetPlayer(*me, playerGuid))
                            if (player->IsAlive() && me->GetAnyOwner() == player)
                                if (BrawlersGuild* brawlerGuild = player->GetBrawlerGuild())
                                    brawlerGuild->BossReport(player->GetGUID(), true);
                    });
                }
            }
        }

        void UpdateAI(uint32 diff) override
        {
            if (me->GetEntry() == 115645)
            {
                if (timer_check <= diff)
                {
                    if (Unit* owner = me->GetAnyOwner())
                    {
                        if (!owner->IsAlive())
                            KilledUnit(owner);
                    }
                    else
                        timer_check = 500;
                }
                else
                    timer_check -= diff;
            }
        }
    }

