struct boss_kargath_bladefist : public BossAI
{
    enum eTalks
    {
        Intro1,
        Intro2,
        Aggro,
        BerserkerRush,
        ChainHurl,
        Impale,
        Berserk,
        FlamePillar,
        Slay,
        Death,

        MargokNearDeath = 2
    };

    enum eActions
    {
