                    Talk(SAY_S_SOLAR_COLLAPSE);
                    DoCast(SPELL_SOLAR_COLLAPSE_FILTER);
                    events.RescheduleEvent(EVENT_SOLAR_COLLAPSE, globalTimer);
                    break;
                case EVENT_COLLAPSE_OF_NIGHT:
                    DoCast(SPELL_COLLAPSE_OF_NIGHT);
