edits.old:
struct boss_helya_tov : BossAI
{
    explicit boss_helya_tov(Creature* creature) : BossAI(creature, Data::BossIDs::HelyaID)
    {
        HelyaIntro = false;
        Intro();
    }

    uint32 berserk;
    uint8 trashDiedCount;
    uint8 trashPhase2Count;
    std::set<ObjectGuid> defeatedGrippingTentacles;
    uint8 eventPhase;
    uint32 power;
    uint32 count;
    uint32 AOEdmg;
    uint32 _checkEvadeTimer;
    bool phase2;
    bool phase3;
    bool HelyaIntro;
    bool checkrephase;
    bool FuryOfTheMaw;
    bool FuryOfTheMawTrash;
    ObjectGuid playerGuid;

    void Reset() override
    {
        _Reset();
        me->SetPower(POWER_ENERGY, 0);
        me->SetMaxPower(POWER_ENERGY, 100);
        me->RemoveAllAuras();
        me->AddUnitState(UNIT_STATE_ROOT);
        me->SetReactState(REACT_AGGRESSIVE);
        me->RemoveAllAreaObjects();
        DoCast(SpellHelyaBluePower);
        RemoveAllDebaffsOnPlayer();
        playerGuid.Clear();
        DespawnAllSummons();

        berserk             = 0;
        eventPhase          = 0;
        trashDiedCount      = 0;
        trashPhase2Count    = 0;
        defeatedGrippingTentacles.clear();
        count               = 0;
        AOEdmg              = 0;
        _checkEvadeTimer    = 0;
        phase2              = false;
        phase3              = false;
        checkrephase        = false;
        FuryOfTheMawTrash   = false;
        FuryOfTheMaw        = false;

        events.RescheduleEvent(EVENT_REANIMATION, 1000);
    }

    void RemoveAllDebaffsOnPlayer()
    {
        instance->DoRemoveAurasDueToSpellOnPlayers(SpellCorruptedAxionAura);
        instance->DoRemoveAurasDueToSpellOnPlayers(SpellCorrupted);
        instance->DoRemoveAurasDueToSpellOnPlayers(SpellBleakEruption);
        instance->DoRemoveAurasDueToSpellOnPlayers(SpellDarkHatred);
        instance->DoRemoveAurasDueToSpellOnPlayers(SpellBilewaterRedox);
        instance->DoRemoveAurasDueToSpellOnPlayers(SpellTaintOfTheSea);
        instance->DoRemoveAurasDueToSpellOnPlayers(SpellFetidRot);
        instance->DoRemoveAurasDueToSpellOnPlayers(SpellOrbofCorrosionOnPlayer);
    }

    void DespawnAllSummons()
    {
        std::list<Creature*> list;
        list.clear();
        me->GetCreatureListWithEntryInGrid(list, 114523, 200.0f);
        me->GetCreatureListWithEntryInGrid(list, 114566, 200.0f);
        if (!list.empty())
            for (auto& sum : list)
                sum->DespawnOrUnsummon();
    }

    void Intro()
    {
        me->SetFlag(UNIT_FIELD_FLAGS, UNIT_FLAG_IMMUNE_TO_PC | UNIT_FLAG_IMMUNE_TO_NPC | UNIT_FLAG_NOT_ATTACKABLE_1);

        if (instance->GetBossState(Data::BossIDs::HelyaID) != DONE)
        {
            for (uint8 i = 0; i < 3; ++i)
                me->SummonCreature(Data::Creatures::AncientBonethrall, Pos_AncientBonethrall[i]);
            for (uint8 i = 0; i < 4; ++i)
                me->SummonCreature(Data::Creatures::DarkSeraph, Pos_DarkSeraph[i]);
            for (uint8 i = 0; i < 5; ++i)
                me->SummonCreature(Data::Creatures::KvaldirTideWitch, Pos_KvaldirTideWitch[i]);
            for (uint8 i = 0; i < 8; ++i)
                me->SummonCreature(Data::Creatures::KvaldirReefcaller, Pos_KvaldirReefcaller[i]);
            for (uint8 i = 0; i < 4; ++i)
                me->SummonCreature(Data::Creatures::DeepbrineMonstrosity, Pos_DeepbrineMonstrosity[i]);

            me->SummonCreature(Data::Creatures::RotsoulGiant, 567.617f, 656.039f, 18.2112f, 0.967337f);
            me->SummonCreature(Data::Creatures::KvaldirCoralMaiden, 561.031f, 665.738f, 18.0399f, 5.4091f);
        }
    }

    void EnterCombat(Unit* /*who*/) override
    {
        _EnterCombat();
        StartEvents(PHASE_1);
        _checkEvadeTimer = 1500;
    }

    void JustDied(Unit* /*killer*/) override
    {
        // Fury's destination cast may still be delayed. Release its current
        // spell reference before the base AI discards the spell event queue.
        me->InterruptNonMeleeSpells(true);
        Talk(SAY_DEATH);
        instance->DoUpdateAchievementCriteria(CRITERIA_TYPE_COMPLETE_DUNGEON_ENCOUNTER, 2008);
        me->RemoveAllAreaObjects();
        RemoveAllDebaffsOnPlayer();
        DespawnAllSummons();
        _JustDied();
    }

    void EnterEvadeMode() override
    {
        me->InterruptNonMeleeSpells(true);
        Talk(SAY_INTRO_1);
        me->NearTeleportTo(524.031f, 699.055f, 5.17631f, 4.29875f);

        BossAI::EnterEvadeMode();
    }

    void SummonedCreatureDies(Creature* summon, Unit* /*killer*/) override
    {
        switch (summon->GetEntry())
        {
            case Data::Creatures::DeepbrineMonstrosity:
            case Data::Creatures::KvaldirReefcaller:
            case Data::Creatures::KvaldirTideWitch:
            case Data::Creatures::DarkSeraph:
            case Data::Creatures::RotsoulGiant:
            case Data::Creatures::AncientBonethrall:
            case Data::Creatures::KvaldirCoralMaiden:
                trashDiedCount++;

                if (!HelyaIntro)
                {
                    HelyaIntro = true;
                    DoAction(ACTION_2);
                }
                break;
            case Data::Creatures::GrippingTentacle:
                if (eventPhase != PHASE_2 || !defeatedGrippingTentacles.insert(summon->GetGUID()).second)
                    return;

                trashPhase2Count++;
                // Each of the nine tentacles wounds Helya for 2% maximum health.
                // This bypasses her phase-two damage immunity without a killing blow.
                {
                    uint64 const wound = me->CountPctFromMaxHealth(2);
                    uint64 const health = me->GetHealth();
                    me->SetHealth(health > wound ? health - wound : 1);
                }
                break;
        }

        if (trashDiedCount == 26 && eventPhase == 0)
        {
            Talk(SAY_INTRO_3);
            me->RemoveFlag(UNIT_FIELD_FLAGS, UNIT_FLAG_IMMUNE_TO_PC | UNIT_FLAG_IMMUNE_TO_NPC | UNIT_FLAG_NOT_ATTACKABLE_1);
        }

        if (trashPhase2Count == 9 && eventPhase == PHASE_2)
            StartEvents(PHASE_3);
    }

    void SetPower(Powers power, int32 value) override
    {
        if (power == POWER_ENERGY)
        {
            if (value == 100 && eventPhase == PHASE_1)
            {
                if (!me->HasUnitState(UNIT_STATE_CASTING))
                {
                    DoCast(SpellBilewaterBreath);
                    Talk(SAY_BILEWATER_BREATH);
                    me->AddDelayedEvent(500, [=]() -> void { me->SetPower(POWER_ENERGY, 0); });
                }
            }

            if (value == 100 && eventPhase == PHASE_3)
            {
                if (!me->HasUnitState(UNIT_STATE_CASTING))
                {
                    DoCast(SpellCorruptedBreath);
                    Talk(SAY_CORRUPTED_BREATH);
                    me->AddDelayedEvent(500, [=]() -> void { me->SetPower(POWER_ENERGY, 0); });
                }
            }
        }

        if (power == POWER_ALTERNATE)
        {
            if (value == 100)
            {
                if (!me->HasUnitState(UNIT_STATE_CASTING))
                {
                    if (IsHeroicPlusRaid() && eventPhase == PHASE_2 && !FuryOfTheMaw)
                    {
                        FuryOfTheMaw = true;
                        me->AddDelayedCombat(5000, [=]() -> void
                        {
                            if (eventPhase != PHASE_2 || !me->isInCombat())
                                return;

                            FuryOfTheMawTrash = false;
                            DoCast(SpellFureOfTheMawLong);
                            FuryOfTheMaw = false;
                            me->SetPower(POWER_ALTERNATE, 0);
                        });
                    }
                    else if (IsLfrRaid() || IsNormalRaid())
                    {
                        if (eventPhase == PHASE_2)
                        {
                            DoCast(SpellFuryoftheMaw);
                            events.RescheduleEvent(EVENT_FURY_OF_THE_MAW_CLEAN_AT, 4000);
                            me->AddDelayedEvent(500, [=]() -> void { me->SetPower(POWER_ALTERNATE, 0); });
                        }
                    }

                    if (eventPhase == PHASE_3)
                    {
                        FuryOfTheMawTrash = false;
                        DoCast(SpellFuryoftheMaw);
                        events.RescheduleEvent(EVENT_FURY_OF_THE_MAW_CLEAN_AT, 4000);
                        me->AddDelayedEvent(500, [=]() -> void { me->SetPower(POWER_ALTERNATE, 0); });
                    }
                }
            }
        }
    }

    void StartEvents(uint8 phase)
    {
        events.Reset();
        eventPhase = phase;

        switch (phase)
        {
        case PHASE_1:
            Talk(SAY_AGGRO);
            AOEdmg = 1000;
            me->SetPower(POWER_ENERGY, 79);

            if (IsMythicRaid())
            {
                events.RescheduleEvent(EVENT_TAINT_OF_THE_SEA, 15500);
                events.RescheduleEvent(EVENT_TENTECLE_STRIKE, 35000);
                events.RescheduleEvent(EVENT_ORB_OF_CURRUPTION, 14000);
            }
            else if (IsHeroicRaid())
            {
                events.RescheduleEvent(EVENT_TAINT_OF_THE_SEA, 19500);
                events.RescheduleEvent(EVENT_TENTECLE_STRIKE, 36000);
                events.RescheduleEvent(EVENT_ORB_OF_CURRUPTION, 29000);
            }
            else if (IsNormalRaid() || IsLfrRaid())
            {
                events.RescheduleEvent(EVENT_TAINT_OF_THE_SEA, IsLfrRaid() ? 21800 : 12000);
                events.RescheduleEvent(EVENT_TENTECLE_STRIKE, 53000);
                events.RescheduleEvent(EVENT_ORB_OF_CURRUPTION, 18000);
            }

            if (IsHeroicPlusRaid())
                berserk = 660000; // 11 min
            break;
        case PHASE_2:
            events.RescheduleEvent(EVENT_TELEPORT_OUTSIDE, 1000);
            checkrephase = true;
            me->CastStop();
            DoCast(SpellRemoveDebuffs);
            DoCast(SpellHelyaImmunityDamage);
            DoCast(SpellHelyaAltPower);
            DoCast(SpellHelyaReuse);

            me->AttackStop();
            me->SetReactState(REACT_PASSIVE);
            me->SetPower(POWER_ENERGY, 0);
            me->RemoveAura(SpellHelyaBluePower);
            me->RemoveAura(SpellCorrosiveNova);
            me->SummonCreatureGroup(3);
            me->AddDelayedCombat(5000, [=]() -> void
            {
                if (eventPhase != PHASE_2)
                    return;

                DoCast(SpellHelyaReuse);
                Talk(SAY_PHASE_2);
                events.RescheduleEvent(EVENT_TORRENT, 9000);
                events.RescheduleEvent(EVENT_REANIMATION, 30000);
                if (IsLfrRaid() || IsNormalRaid())
                {
                    DoCast(SpellHelyaAltPowerRegen);
                    events.RescheduleEvent(EVENT_FURY_OF_THE_MAW, 2000);
                }
                else if (IsHeroicPlusRaid())
                    me->SetPower(POWER_ALTERNATE, 100);
            });
            break;
        case PHASE_3:
            events.RescheduleEvent(EVENT_TELEPORT_HOME, 2000);
            DoCast(SpellHelyaReuse);
            me->CastStop();
            me->RemoveAura(SpellFureOfTheMawLong);
            me->RemoveAura(SpellHelyaImmunityDamage);
            me->RemoveAura(SpellHelyaAltPowerRegen);
            me->RemoveAura(SpellTorrent);
            me->AddDelayedCombat(5000, [=]() -> void
            {
                if (eventPhase != PHASE_3)
                    return;

                Talk(SAY_PHASE_3);
                me->SetPower(POWER_ENERGY, 61);
                me->SetPower(POWER_ALTERNATE, 42);
                me->SetReactState(REACT_AGGRESSIVE);
                me->RemoveAura(SpellBuildingStorm);
                me->RemoveAura(SpellCorrosiveNova);
                me->AddDelayedCombat(1500, [=]() -> void
                {
                    if (eventPhase != PHASE_3)
                        return;

                    DoCast(SpellHelyaAltPowerRegen);
                    checkrephase = false;
                    // Phase three has its own Taint cadence after Helya returns.
                    events.RescheduleEvent(EVENT_TAINT_OF_THE_SEA, IsMythicRaid() ? 1 : 24500);
                });
                DoCast(SpellHelyaReuse);
                DoCast(SpellHelyaPurplePower);
                events.RescheduleEvent(EVENT_REANIMATION, 52000);
                if (IsMythicRaid())
                    events.RescheduleEvent(EVENT_ORB_OF_CORROSION, 6000);
                else if (IsHeroicRaid())
                    events.RescheduleEvent(EVENT_ORB_OF_CORROSION, 14000);
                else if (IsNormalRaid() || IsLfrRaid())
                    events.RescheduleEvent(EVENT_ORB_OF_CORROSION, 18000);
            });
            break;
        }
    }

    void DamageTakenAfterScaling(Unit* attacker, uint32& damage, DamageEffectType /*dmgType*/) override
    {
        if (eventPhase == PHASE_2)
        {
            damage = 0;
            return;
        }

        if (!damage || phase2)
            return;

        // The first spell's damage can precede Spell::CombatStart.
        if (instance->GetBossState(Data::BossIDs::HelyaID) != IN_PROGRESS)
        {
            if (!attacker || eventPhase != 0 || me->getFaction() != 16 ||
                instance->GetBossState(Data::BossIDs::HelyaID) == DONE ||
                me->HasFlag(UNIT_FIELD_FLAGS, UNIT_FLAG_IMMUNE_TO_PC | UNIT_FLAG_IMMUNE_TO_NPC | UNIT_FLAG_NOT_ATTACKABLE_1))
                return;

            me->SetInCombatWith(attacker);
            if (instance->GetBossState(Data::BossIDs::HelyaID) != IN_PROGRESS)
                return;
        }

        if (eventPhase != PHASE_1)
            return;

        uint64 const maximum = me->GetMaxHealth(attacker);
        if (!maximum)
            return;

        uint64 const health = me->GetHealth(attacker);
        uint64 const threshold = CalculatePct(maximum, 65);
        if (health <= threshold || damage >= health - threshold)
        {
            damage = 0;
            me->SetHealth(std::max<uint64>(1, me->CountPctFromMaxHealth(65)));
            TC_LOG_DEBUG("scripts", "Trial of Valor Helya: phase two after final scaled damage");
            phase2 = true;
            StartEvents(PHASE_2);
        }
    }

    void SpellHit(Unit* owner, SpellInfo const* spell) override
    {
        switch (spell->Id)
        {
        case SpellBilewaterLiquefactionKill:
            if (SpellInfo const* spellInfo = sSpellMgr->GetSpellInfo(227992))
            {
                float damage = spellInfo->GetEffect(EFFECT_0, owner->GetSpawnMode())->CalcValue();
                float healthPct = owner->GetHealthPct() > 5.0f ? owner->GetHealthPct() : 5.0f;
                damage = CalculatePct(damage, healthPct);
                me->CastCustomSpell(owner, SpellBilewaterLiquefactionDmg, &damage, &healthPct, nullptr, true);
            }
            break;
        case SpellOrbOfCorruption:
        {
            if (me->GetMap() && (me->GetMap()->GetSpawnMode() == DIFFICULTY_NORMAL_RAID) || (me->GetMap()->GetSpawnMode() == DIFFICULTY_LFR_RAID))
                count = 2;
            else if (me->GetMap() && (me->GetMap()->GetSpawnMode() == DIFFICULTY_MYTHIC_RAID) || (me->GetMap()->GetSpawnMode() == DIFFICULTY_HEROIC_RAID))
                count = 3;

            std::list<Player*> playerList;
            GetPlayerListInGrid(playerList, me, 300.0f);
            Trinity::Containers::RandomResizeList(playerList, count);

            if (playerList.empty())
                return;

            for (auto& player : playerList)
            {
                DoCast(player, SpellOrbOfCorruptionVisual, true);

                ObjectGuid const targetGuid = player->GetGUID();
                Position pos = player->GetPosition();
                pos.m_positionX -= 6.0f;
                pos.m_positionY -= 6.0f;
                me->AddDelayedCombat(2000, [this, pos, targetGuid]()
                {
                    if (eventPhase == PHASE_1 && me->isInCombat() && me->IsAlive())
                        me->SummonCreature(Data::Creatures::OrbOfCorruption, pos, targetGuid, TEMPSUMMON_TIMED_DESPAWN, 9000);
                });
            }
            break;
        }
        case SpellOrbOfCorrosion:
        {
            if (me->GetMap() && (me->GetMap()->GetSpawnMode() == DIFFICULTY_NORMAL_RAID) || (me->GetMap()->GetSpawnMode() == DIFFICULTY_LFR_RAID))
                count = 2;
            else if (me->GetMap() && (me->GetMap()->GetSpawnMode() == DIFFICULTY_MYTHIC_RAID) || (me->GetMap()->GetSpawnMode() == DIFFICULTY_HEROIC_RAID))
                count = 3;

            std::list<Player*> playerList;
            GetPlayerListInGrid(playerList, me, 300.0f);
            Trinity::Containers::RandomResizeList(playerList, count);

            if (playerList.empty())
                return;

            for (auto& player : playerList)
            {
                ObjectGuid const targetGuid = player->GetGUID();

                DoCast(player, SpellOrbOfCorrosionVisual, true);

                Position pos = player->GetPosition();
                pos.m_positionX -= 6.0f;
                pos.m_positionY -= 6.0f;
                me->AddDelayedCombat(2000, [this, pos, targetGuid]()
                {
                    if (eventPhase == PHASE_3 && me->isInCombat() && me->IsAlive())
                        me->SummonCreature(Data::Creatures::OrbOfCorrosion, pos, targetGuid, TEMPSUMMON_TIMED_DESPAWN, 9000);
                });
            }
            break;
        }
        case SpellBilewaterBreath:
        {
            uint8 count = me->GetMap()->GetPlayersCountExceptGMs();

            if (count <= 10)
                count = 2;
            else if (count <= 15)
                count = 3;
            else if (count <= 20)
                count = 4;
            else if (count <= 25)
                count = 5;
            else
                count = 6;

            float dist = 40.0f;
            for (uint8 i = 0; i < count; ++i)
            {
                dist += 11.0f;
                float x, y;
                me->GetNearPoint2D(x, y, dist, me->GetOrientation(), false);
                float z = me->GetHeight(x, y, MAX_HEIGHT, true, MAX_FALL_DISTANCE);
                if (z > INVALID_HEIGHT)
                    me->CastSpell(x, y, z, SpellBilewaterBreathNpc, true);
            }
            break;
        }
        case SpellCorruptedBreath:
        {
            if (!IsHeroicPlusRaid())
                return;

            uint32 countTarget = 0;

            if (IsMythicRaid())
                countTarget = 5;
            else
                countTarget = 3;

            float dist = 30.0f;
            for (uint8 i = 0; i < countTarget; ++i)
            {
                dist += 13.0f;
                float x, y;
                me->GetNearPoint2D(x, y, dist, me->GetOrientation(), false);
                // A missile can land above/below Helya. Walking-position helpers
                // reject those height changes and can return the caster instead.
                float z = me->GetHeight(x, y, MAX_HEIGHT, true, MAX_FALL_DISTANCE);
                if (z > INVALID_HEIGHT)
                    me->CastSpell(x, y, z, SpellCorruptedAxion, true);
            }
            break;
        }
        case SpellOrbOfCorrosionShare:
            DoCast(owner, SpellOrbOfCorrosionDmg, true);
            break;
        }
    }

    void SpellHitTarget(Unit* target, SpellInfo const* spell) override
    {
        switch (spell->Id)
        {
        case SpellBilewaterBreathDmg:
            DoCast(target, SpellBilewaterRedox, true);
            break;
        case SpellCorruptedBreathDmg:
            DoCast(target, SpellDarkHatred, false);
            break;
        }
    }

    void SpellFinishCast(SpellInfo const* spell) override
    {
        switch (spell->Id)
        {
        case SpellFuryOfTheMawAT:
            if (IsHeroicPlusRaid())
            {
                if (!FuryOfTheMawTrash)
                {
                    events.RescheduleEvent(EVENT_BOAT, 500);
                    events.ScheduleEvent(EVENT_SUMMON_SKELETION, 31000);
                    events.ScheduleEvent(EVENT_SUMMON_SKELETION, 41000);
                    FuryOfTheMawTrash = true;
                }
                events.RescheduleEvent(EVENT_FURY_OF_THE_MAW_CLEAN_AT, 3000);
            }
            else if (IsLfrRaid() || IsNormalRaid())
            {
                if (eventPhase == PHASE_3 || eventPhase == PHASE_2)
                {
                    events.RescheduleEvent(EVENT_BOAT, 500);
                    events.ScheduleEvent(EVENT_SUMMON_SKELETION, 31000);
                    events.ScheduleEvent(EVENT_SUMMON_SKELETION, 41000);
                }
            }
            break;
        }
    }

    void DoAction(int32 const action) override
    {
        switch (action)
        {
        case ACTION_1:
            if (eventPhase != PHASE_2 || !me->isInCombat() || instance->GetBossState(Data::BossIDs::HelyaID) != IN_PROGRESS)
                break;

            DoCast(SpellHelyaAltPowerRegen);
            events.RescheduleEvent(EVENT_TORRENT, 2000);
            break;
        case ACTION_2:
            if (instance->GetBossState(Data::BossIDs::GarmID) == DONE)
            {
                Talk(SAY_INTRO_1);
                me->AddDelayedEvent(13000, [=]() -> void { Talk(SAY_INTRO_2); });
            }
            break;
        default:
            break;
        }
    }

    void JustSummoned(Creature* sum) override
    {
        summons.Summon(sum);

        switch (sum->GetEntry())
        {
        case Data::Creatures::OrbOfCorruption:
            if (auto target = ObjectAccessor::GetUnit(*sum, sum->GetTargetGUID()))
                sum->CastSpell(target, SpellOrbofCorruptionOnPlayer, true);
            break;
        case Data::Creatures::OrbOfCorrosion:
            if (auto target = ObjectAccessor::GetUnit(*sum, sum->GetTargetGUID()))
                sum->CastSpell(target, SpellOrbofCorrosionOnPlayer, true);
            break;
        case Data::Creatures::NightWatchMariner:
            if (eventPhase == PHASE_3)
                sum->AddAura(SpellRallyOfTheKvaldir, sum);
            break;
        default:
            break;
        }
    }

    uint32 GetData(uint32 type) const override
    {
        if (type == Data::BossIDs::HelyaID)
            return eventPhase;
        return 0;
    }

    void UpdateAI(uint32 diff) override
    {
        if (!UpdateVictim() && me->isInCombat())
            return;

        if (_checkEvadeTimer)
        {
            if (_checkEvadeTimer <= diff)
            {
                _checkEvadeTimer = 1500;

                if (auto victim = me->getVictim())
                {
                    if (me->GetDistance(victim) > 90.0f && eventPhase != PHASE_2)
                        EnterEvadeMode();
                    else if (me->GetDistance(victim) > 140.0f && eventPhase == PHASE_2)
                        EnterEvadeMode();
                }
            }
            else
                _checkEvadeTimer -= diff;
        }

        events.Update(diff);

        if (me->HasUnitState(UNIT_STATE_CASTING))
            return;

        if (uint32 eventId = events.ExecuteEvent())
        {
            switch (eventId)
            {
            case EVENT_TAINT_OF_THE_SEA:
            {
                if (eventPhase == PHASE_1 || eventPhase == PHASE_3)
                {
                    std::list<Player*> targets;
                    for (auto reference : me->getThreatManager().getThreatList())
                        if (Unit* unit = reference->getTarget())
                            if (Player* player = unit->ToPlayer())
                                if (player->IsAlive() && player->IsInWorld() && !player->isGameMaster() && player->GetMap() == me->GetMap())
                                    targets.push_back(player);

                    // The active tank is always one of the targets; pets must not consume a slot.
                    uint32 count = IsMythicRaid() ? 5 : 3;
                    if (Unit* victim = me->getVictim())
                        if (Player* tank = victim->ToPlayer())
                            if (std::find(targets.begin(), targets.end(), tank) != targets.end())
                            {
                                me->AddAura(SpellTaintOfTheSea, tank);
                                targets.remove(tank);
                                --count;
                            }

                    Trinity::Containers::RandomResizeList(targets, count);
                    for (Player* target : targets)
                        me->AddAura(SpellTaintOfTheSea, target);
                    if (eventPhase == PHASE_3)
                        events.RescheduleEvent(EVENT_TAINT_OF_THE_SEA, IsMythicRaid() ? 20000 : 28000);
                    else
                        events.RescheduleEvent(EVENT_TAINT_OF_THE_SEA, IsLfrRaid() ? 17000 : 12100);
                }
                break;
            }
            case EVENT_TENTECLE_STRIKE:
                if (eventPhase == PHASE_1)
                {
                    me->SummonCreature(Data::Creatures::StrikingTentacle, StrikingTentacle[urand(0, 2)], TEMPSUMMON_TIMED_DESPAWN, 9000);

                    if (IsMythicRaid())
                        events.RescheduleEvent(EVENT_TENTECLE_STRIKE, 35000);
                    else
                        events.RescheduleEvent(EVENT_TENTECLE_STRIKE, 30000);
                }
                break;
            case EVENT_ORB_OF_CURRUPTION:
                if (eventPhase == PHASE_1)
                {
                    DoCast(SpellOrbOfCorruption);

                    if (IsMythicRaid())
                        events.RescheduleEvent(EVENT_ORB_OF_CURRUPTION, 23000);
                    else
                        events.RescheduleEvent(EVENT_ORB_OF_CURRUPTION, 26000);
                }
                break;
            case EVENT_ORB_OF_CORROSION:
                if (eventPhase == PHASE_3)
                {
                    Talk(SAY_ORB_OF_CORROSION);
                    DoCast(SpellOrbOfCorrosion);

                    if (IsMythicRaid())
                        events.RescheduleEvent(EVENT_ORB_OF_CORROSION, 13000);
                    else
                        events.RescheduleEvent(EVENT_ORB_OF_CORROSION, 17000);
                }
                break;
            case EVENT_TORRENT:
                if (!me->HasUnitState(UNIT_STATE_CASTING))
                {
                    if (eventPhase == PHASE_2)
                    {
                        if (!me->HasAura(SpellFureOfTheMawLong))
                        {
                            power = me->GetPower(POWER_ALTERNATE);

                            if (power <= 95)
                            {
                                DoCast(SpellTorrent);
                                events.RescheduleEvent(EVENT_TORRENT, 10000);
                            }
                        }
                    }
                }
                break;
            case EVENT_TELEPORT_OUTSIDE:
                me->NearTeleportTo(553.95f, 733.01f, 5.1663f, 4.03013f);
                break;
            case EVENT_TELEPORT_HOME:
                me->NearTeleportTo(524.031f, 699.055f, 5.17631f, 4.29875f);
                break;
            case EVENT_FURY_OF_THE_MAW:
                DoCast(SpellFuryOfTheMawAT);
                events.RescheduleEvent(EVENT_FURY_OF_THE_MAW_CLEAN_AT, 3000);
                break;
            case EVENT_FURY_OF_THE_MAW_CLEAN_AT:
                me->RemoveAreaObject(SpellBilewaterLiquefactionDmg);
                me->RemoveAreaObject(SpellDecay);
                break;
            case EVENT_REANIMATION:
                if (eventPhase == 0)
                {
                    DoCast(SpellReanimation1);
                    DoCast(SpellReanimation2);
                    events.RescheduleEvent(EVENT_REANIMATION, 15000);
                }
                break;
            case EVENT_SUMMON_SKELETION:
                for (uint8 i = 0; i < 10; ++i)
                    me->SummonCreature(Data::Creatures::DecayingMinion, skeletionPos[i], TEMPSUMMON_CORPSE_TIMED_DESPAWN, 5000);
                break;
            case EVENT_BOAT:
                if (eventPhase == PHASE_2)
                {
                    me->SummonCreature(Data::Creatures::KvaldirLongboat, 569.39f, 857.6201f, 0.00213f, 4.433769f, TEMPSUMMON_TIMED_DESPAWN, 5000);
                    me->SummonCreature(Data::Creatures::KvaldirLongboat, 638.672f, 817.6201f, 0.00213f, 3.943812f, TEMPSUMMON_TIMED_DESPAWN, 5000);
                    me->AddDelayedCombat(4000, [=]() -> void
                    {
                        me->SummonCreature(Data::Creatures::Grimelord, 458.674f, 639.483f, 7.53757f, 4.433769f, TEMPSUMMON_CORPSE_TIMED_DESPAWN, 5000);
                        me->SummonCreature(Data::Creatures::NightWatchMariner, 516.007f, 614.179f, 5.5823f, 3.943812f, TEMPSUMMON_CORPSE_TIMED_DESPAWN, 5000);
                    });
                    if (IsMythicRaid())
                    {
                        me->SummonCreature(Data::Creatures::HelarjarMistwatcher, 564.366f, 653.4237f, 17.9559f, 2.401197f, TEMPSUMMON_CORPSE_TIMED_DESPAWN, 5000);
                        me->SummonCreature(Data::Creatures::HelarjarMistwatcher, 469.7802f, 703.5213f, 17.96658f, 6.12398f, TEMPSUMMON_CORPSE_TIMED_DESPAWN, 5000);
                    }
                }
                else if (eventPhase == PHASE_3)
                {
                    me->AddDelayedCombat(4000, [=]() -> void
                    {
                        me->SummonCreature(Data::Creatures::NightWatchMariner, 516.007f, 614.179f, 5.5823f, 3.943812f, TEMPSUMMON_CORPSE_TIMED_DESPAWN, 5000);
                    });
                    me->SummonCreature(Data::Creatures::KvaldirLongboat, 638.672f, 817.6201f, 0.00213f, 3.943812f, TEMPSUMMON_TIMED_DESPAWN, 5000);
                }
                break;
            }
        }

        if (berserk)
        {
            if (berserk <= diff)
            {
                berserk = 0;
                DoCast(me, SpellBerserk, true);
            }
            else
                berserk -= diff;
        }

        if (AOEdmg)
        {
            if (AOEdmg <= diff)
            {
                if (eventPhase != PHASE_2)
                {
                    if (checkrephase)
                        return;

                    if (auto victim = me->getVictim())
                        if (!me->IsWithinMeleeRange(victim))
                            DoCast(SpellCorrosiveNova);
                }
            }
            else
                AOEdmg -= diff;
        }
        DoMeleeAttackIfReady();
    }
}

edits.new:
struct boss_helya_tov : BossAI
{
    explicit boss_helya_tov(Creature* creature) : BossAI(creature, Data::BossIDs::HelyaID)
    {
        HelyaIntro = false;
        Intro();
    }

    uint32 berserk;
    uint8 trashDiedCount;
    uint8 trashPhase2Count;
    std::set<ObjectGuid> defeatedGrippingTentacles;
    uint8 eventPhase;
    uint32 power;
    uint32 count;
    uint32 AOEdmg;
    uint32 _checkEvadeTimer;
    bool phase2;
    bool phase3;
    bool HelyaIntro;
    bool checkrephase;
    bool FuryOfTheMaw;
    bool FuryOfTheMawTrash;
    ObjectGuid playerGuid;

    void Reset() override
    {
        _Reset();
        me->SetPower(POWER_ENERGY, 0);
        me->SetMaxPower(POWER_ENERGY, 100);
        me->RemoveAllAuras();
        me->AddUnitState(UNIT_STATE_ROOT);
        me->SetReactState(REACT_AGGRESSIVE);
        me->RemoveAllAreaObjects();
        DoCast(SpellHelyaBluePower);
        RemoveAllDebaffsOnPlayer();
        playerGuid.Clear();
        DespawnAllSummons();

        berserk             = 0;
        eventPhase          = 0;
        trashDiedCount      = 0;
        trashPhase2Count    = 0;
        defeatedGrippingTentacles.clear();
        count               = 0;
        AOEdmg              = 0;
        _checkEvadeTimer    = 0;
        phase2              = false;
        phase3              = false;
        checkrephase        = false;
        FuryOfTheMawTrash   = false;
        FuryOfTheMaw        = false;

        events.RescheduleEvent(EVENT_REANIMATION, 1000);
    }

    void RemoveAllDebaffsOnPlayer()
    {
        instance->DoRemoveAurasDueToSpellOnPlayers(SpellCorruptedAxionAura);
        instance->DoRemoveAurasDueToSpellOnPlayers(SpellCorrupted);
        instance->DoRemoveAurasDueToSpellOnPlayers(SpellBleakEruption);
        instance->DoRemoveAurasDueToSpellOnPlayers(SpellDarkHatred);
        instance->DoRemoveAurasDueToSpellOnPlayers(SpellBilewaterRedox);
        instance->DoRemoveAurasDueToSpellOnPlayers(SpellTaintOfTheSea);
        instance->DoRemoveAurasDueToSpellOnPlayers(SpellFetidRot);
        instance->DoRemoveAurasDueToSpellOnPlayers(SpellOrbofCorrosionOnPlayer);
    }

    void DespawnAllSummons()
    {
        std::list<Creature*> list;
        list.clear();
        me->GetCreatureListWithEntryInGrid(list, 114523, 200.0f);
        me->GetCreatureListWithEntryInGrid(list, 114566, 200.0f);
        if (!list.empty())
            for (auto& sum : list)
                sum->DespawnOrUnsummon();
    }

    void Intro()
    {
        me->SetFlag(UNIT_FIELD_FLAGS, UNIT_FLAG_IMMUNE_TO_PC | UNIT_FLAG_IMMUNE_TO_NPC | UNIT_FLAG_NOT_ATTACKABLE_1);

        if (instance->GetBossState(Data::BossIDs::HelyaID) != DONE)
        {
            for (uint8 i = 0; i < 3; ++i)
                me->SummonCreature(Data::Creatures::AncientBonethrall, Pos_AncientBonethrall[i]);
            for (uint8 i = 0; i < 4; ++i)
                me->SummonCreature(Data::Creatures::DarkSeraph, Pos_DarkSeraph[i]);
            for (uint8 i = 0; i < 5; ++i)
                me->SummonCreature(Data::Creatures::KvaldirTideWitch, Pos_KvaldirTideWitch[i]);
            for (uint8 i = 0; i < 8; ++i)
                me->SummonCreature(Data::Creatures::KvaldirReefcaller, Pos_KvaldirReefcaller[i]);
            for (uint8 i = 0; i < 4; ++i)
                me->SummonCreature(Data::Creatures::DeepbrineMonstrosity, Pos_DeepbrineMonstrosity[i]);

            me->SummonCreature(Data::Creatures::RotsoulGiant, 567.617f, 656.039f, 18.2112f, 0.967337f);
            me->SummonCreature(Data::Creatures::KvaldirCoralMaiden, 561.031f, 665.738f, 18.0399f, 5.4091f);
        }
    }

    void EnterCombat(Unit* /*who*/) override
    {
        _EnterCombat();
        StartEvents(PHASE_1);
        _checkEvadeTimer = 1500;
    }

    void JustDied(Unit* /*killer*/) override
    {
        // Fury's destination cast may still be delayed. Release its current
        // spell reference before the base AI discards the spell event queue.
        me->InterruptNonMeleeSpells(true);
        Talk(SAY_DEATH);
        instance->DoUpdateAchievementCriteria(CRITERIA_TYPE_COMPLETE_DUNGEON_ENCOUNTER, 2008);
        me->RemoveAllAreaObjects();
        RemoveAllDebaffsOnPlayer();
        DespawnAllSummons();
        _JustDied();
    }

    void EnterEvadeMode() override
    {
        me->InterruptNonMeleeSpells(true);
        Talk(SAY_INTRO_1);
        me->NearTeleportTo(524.031f, 699.055f, 5.17631f, 4.29875f);

        BossAI::EnterEvadeMode();
    }

    void SummonedCreatureDies(Creature* summon, Unit* /*killer*/) override
    {
        switch (summon->GetEntry())
        {
            case Data::Creatures::DeepbrineMonstrosity:
            case Data::Creatures::KvaldirReefcaller:
            case Data::Creatures::KvaldirTideWitch:
            case Data::Creatures::DarkSeraph:
            case Data::Creatures::RotsoulGiant:
            case Data::Creatures::AncientBonethrall:
            case Data::Creatures::KvaldirCoralMaiden:
                trashDiedCount++;

                if (!HelyaIntro)
                {
                    HelyaIntro = true;
                    DoAction(ACTION_2);
                }
                break;
            case Data::Creatures::GrippingTentacle:
                if (eventPhase != PHASE_2 || !defeatedGrippingTentacles.insert(summon->GetGUID()).second)
                    return;

                trashPhase2Count++;
                // Each of the nine tentacles wounds Helya for 2% maximum health.
                // This bypasses her phase-two damage immunity without a killing blow.
                {
                    uint64 const wound = me->CountPctFromMaxHealth(2);
                    uint64 const health = me->GetHealth();
                    me->SetHealth(health > wound ? health - wound : 1);
                }
                break;
        }

        if (trashDiedCount == 26 && eventPhase == 0)
        {
            Talk(SAY_INTRO_3);
            me->RemoveFlag(UNIT_FIELD_FLAGS, UNIT_FLAG_IMMUNE_TO_PC | UNIT_FLAG_IMMUNE_TO_NPC | UNIT_FLAG_NOT_ATTACKABLE_1);
        }

        if (trashPhase2Count == 9 && eventPhase == PHASE_2)
            StartEvents(PHASE_3);
    }

    void SetPower(Powers power, int32 value) override
    {
        if (power == POWER_ENERGY)
        {
            if (value == 100 && eventPhase == PHASE_1)
            {
                if (!me->HasUnitState(UNIT_STATE_CASTING))
                {
                    DoCast(SpellBilewaterBreath);
                    Talk(SAY_BILEWATER_BREATH);
                    me->AddDelayedEvent(500, [=, aiLifetimeGuard = std::weak_ptr<uint8>(_delayedAILifetimeGuard)]() -> void { if (aiLifetimeGuard.expired()) return; me->SetPower(POWER_ENERGY, 0); });
                }
            }

            if (value == 100 && eventPhase == PHASE_3)
            {
                if (!me->HasUnitState(UNIT_STATE_CASTING))
                {
                    DoCast(SpellCorruptedBreath);
                    Talk(SAY_CORRUPTED_BREATH);
                    me->AddDelayedEvent(500, [=, aiLifetimeGuard = std::weak_ptr<uint8>(_delayedAILifetimeGuard)]() -> void { if (aiLifetimeGuard.expired()) return; me->SetPower(POWER_ENERGY, 0); });
                }
            }
        }

        if (power == POWER_ALTERNATE)
        {
            if (value == 100)
            {
                if (!me->HasUnitState(UNIT_STATE_CASTING))
                {
                    if (IsHeroicPlusRaid() && eventPhase == PHASE_2 && !FuryOfTheMaw)
                    {
                        FuryOfTheMaw = true;
                        me->AddDelayedCombat(5000, [=, aiLifetimeGuard = std::weak_ptr<uint8>(_delayedAILifetimeGuard)]() -> void
                        {
                            if (aiLifetimeGuard.expired()) return;
                            if (eventPhase != PHASE_2 || !me->isInCombat())
                                return;

                            FuryOfTheMawTrash = false;
                            DoCast(SpellFureOfTheMawLong);
                            FuryOfTheMaw = false;
                            me->SetPower(POWER_ALTERNATE, 0);
                        });
                    }
                    else if (IsLfrRaid() || IsNormalRaid())
                    {
                        if (eventPhase == PHASE_2)
                        {
                            DoCast(SpellFuryoftheMaw);
                            events.RescheduleEvent(EVENT_FURY_OF_THE_MAW_CLEAN_AT, 4000);
                            me->AddDelayedEvent(500, [=, aiLifetimeGuard = std::weak_ptr<uint8>(_delayedAILifetimeGuard)]() -> void { if (aiLifetimeGuard.expired()) return; me->SetPower(POWER_ALTERNATE, 0); });
                        }
                    }

                    if (eventPhase == PHASE_3)
                    {
                        FuryOfTheMawTrash = false;
                        DoCast(SpellFuryoftheMaw);
                        events.RescheduleEvent(EVENT_FURY_OF_THE_MAW_CLEAN_AT, 4000);
                        me->AddDelayedEvent(500, [=, aiLifetimeGuard = std::weak_ptr<uint8>(_delayedAILifetimeGuard)]() -> void { if (aiLifetimeGuard.expired()) return; me->SetPower(POWER_ALTERNATE, 0); });
                    }
                }
            }
        }
    }

    void StartEvents(uint8 phase)
    {
        events.Reset();
        eventPhase = phase;

        switch (phase)
        {
        case PHASE_1:
            Talk(SAY_AGGRO);
            AOEdmg = 1000;
            me->SetPower(POWER_ENERGY, 79);

            if (IsMythicRaid())
            {
                events.RescheduleEvent(EVENT_TAINT_OF_THE_SEA, 15500);
                events.RescheduleEvent(EVENT_TENTECLE_STRIKE, 35000);
                events.RescheduleEvent(EVENT_ORB_OF_CURRUPTION, 14000);
            }
            else if (IsHeroicRaid())
            {
                events.RescheduleEvent(EVENT_TAINT_OF_THE_SEA, 19500);
                events.RescheduleEvent(EVENT_TENTECLE_STRIKE, 36000);
                events.RescheduleEvent(EVENT_ORB_OF_CURRUPTION, 29000);
            }
            else if (IsNormalRaid() || IsLfrRaid())
            {
                events.RescheduleEvent(EVENT_TAINT_OF_THE_SEA, IsLfrRaid() ? 21800 : 12000);
                events.RescheduleEvent(EVENT_TENTECLE_STRIKE, 53000);
                events.RescheduleEvent(EVENT_ORB_OF_CURRUPTION, 18000);
            }

            if (IsHeroicPlusRaid())
                berserk = 660000; // 11 min
            break;
        case PHASE_2:
            events.RescheduleEvent(EVENT_TELEPORT_OUTSIDE, 1000);
            checkrephase = true;
            me->CastStop();
            DoCast(SpellRemoveDebuffs);
            DoCast(SpellHelyaImmunityDamage);
            DoCast(SpellHelyaAltPower);
            DoCast(SpellHelyaReuse);

            me->AttackStop();
            me->SetReactState(REACT_PASSIVE);
            me->SetPower(POWER_ENERGY, 0);
            me->RemoveAura(SpellHelyaBluePower);
            me->RemoveAura(SpellCorrosiveNova);
            me->SummonCreatureGroup(3);
            me->AddDelayedCombat(5000, [=, aiLifetimeGuard = std::weak_ptr<uint8>(_delayedAILifetimeGuard)]() -> void
            {
                if (aiLifetimeGuard.expired()) return;
                if (eventPhase != PHASE_2)
                    return;

                DoCast(SpellHelyaReuse);
                Talk(SAY_PHASE_2);
                events.RescheduleEvent(EVENT_TORRENT, 9000);
                events.RescheduleEvent(EVENT_REANIMATION, 30000);
                if (IsLfrRaid() || IsNormalRaid())
                {
                    DoCast(SpellHelyaAltPowerRegen);
                    events.RescheduleEvent(EVENT_FURY_OF_THE_MAW, 2000);
                }
                else if (IsHeroicPlusRaid())
                    me->SetPower(POWER_ALTERNATE, 100);
            });
            break;
        case PHASE_3:
            events.RescheduleEvent(EVENT_TELEPORT_HOME, 2000);
            DoCast(SpellHelyaReuse);
            me->CastStop();
            me->RemoveAura(SpellFureOfTheMawLong);
            me->RemoveAura(SpellHelyaImmunityDamage);
            me->RemoveAura(SpellHelyaAltPowerRegen);
            me->RemoveAura(SpellTorrent);
            me->AddDelayedCombat(5000, [=, aiLifetimeGuard = std::weak_ptr<uint8>(_delayedAILifetimeGuard)]() -> void
            {
                if (aiLifetimeGuard.expired()) return;
                if (eventPhase != PHASE_3)
                    return;

                Talk(SAY_PHASE_3);
                me->SetPower(POWER_ENERGY, 61);
                me->SetPower(POWER_ALTERNATE, 42);
                me->SetReactState(REACT_AGGRESSIVE);
                me->RemoveAura(SpellBuildingStorm);
                me->RemoveAura(SpellCorrosiveNova);
                me->AddDelayedCombat(1500, [=, aiLifetimeGuard = std::weak_ptr<uint8>(_delayedAILifetimeGuard)]() -> void
                {
                    if (aiLifetimeGuard.expired()) return;
                    if (eventPhase != PHASE_3)
                        return;

                    DoCast(SpellHelyaAltPowerRegen);
                    checkrephase = false;
                    // Phase three has its own Taint cadence after Helya returns.
                    events.RescheduleEvent(EVENT_TAINT_OF_THE_SEA, IsMythicRaid() ? 1 : 24500);
                });
                DoCast(SpellHelyaReuse);
                DoCast(SpellHelyaPurplePower);
                events.RescheduleEvent(EVENT_REANIMATION, 52000);
                if (IsMythicRaid())
                    events.RescheduleEvent(EVENT_ORB_OF_CORROSION, 6000);
                else if (IsHeroicRaid())
                    events.RescheduleEvent(EVENT_ORB_OF_CORROSION, 14000);
                else if (IsNormalRaid() || IsLfrRaid())
                    events.RescheduleEvent(EVENT_ORB_OF_CORROSION, 18000);
            });
            break;
        }
    }

    void DamageTakenAfterScaling(Unit* attacker, uint32& damage, DamageEffectType /*dmgType*/) override
    {
        if (eventPhase == PHASE_2)
        {
            damage = 0;
            return;
        }

        if (!damage || phase2)
            return;

        // The first spell's damage can precede Spell::CombatStart.
        if (instance->GetBossState(Data::BossIDs::HelyaID) != IN_PROGRESS)
        {
            if (!attacker || eventPhase != 0 || me->getFaction() != 16 ||
                instance->GetBossState(Data::BossIDs::HelyaID) == DONE ||
                me->HasFlag(UNIT_FIELD_FLAGS, UNIT_FLAG_IMMUNE_TO_PC | UNIT_FLAG_IMMUNE_TO_NPC | UNIT_FLAG_NOT_ATTACKABLE_1))
                return;

            me->SetInCombatWith(attacker);
            if (instance->GetBossState(Data::BossIDs::HelyaID) != IN_PROGRESS)
                return;
        }

        if (eventPhase != PHASE_1)
            return;

        uint64 const maximum = me->GetMaxHealth(attacker);
        if (!maximum)
            return;

        uint64 const health = me->GetHealth(attacker);
        uint64 const threshold = CalculatePct(maximum, 65);
        if (health <= threshold || damage >= health - threshold)
        {
            damage = 0;
            me->SetHealth(std::max<uint64>(1, me->CountPctFromMaxHealth(65)));
            TC_LOG_DEBUG("scripts", "Trial of Valor Helya: phase two after final scaled damage");
            phase2 = true;
            StartEvents(PHASE_2);
        }
    }

    void SpellHit(Unit* owner, SpellInfo const* spell) override
    {
        switch (spell->Id)
        {
        case SpellBilewaterLiquefactionKill:
            if (SpellInfo const* spellInfo = sSpellMgr->GetSpellInfo(227992))
            {
                float damage = spellInfo->GetEffect(EFFECT_0, owner->GetSpawnMode())->CalcValue();
                float healthPct = owner->GetHealthPct() > 5.0f ? owner->GetHealthPct() : 5.0f;
                damage = CalculatePct(damage, healthPct);
                me->CastCustomSpell(owner, SpellBilewaterLiquefactionDmg, &damage, &healthPct, nullptr, true);
            }
            break;
        case SpellOrbOfCorruption:
        {
            if (me->GetMap() && (me->GetMap()->GetSpawnMode() == DIFFICULTY_NORMAL_RAID) || (me->GetMap()->GetSpawnMode() == DIFFICULTY_LFR_RAID))
                count = 2;
            else if (me->GetMap() && (me->GetMap()->GetSpawnMode() == DIFFICULTY_MYTHIC_RAID) || (me->GetMap()->GetSpawnMode() == DIFFICULTY_HEROIC_RAID))
                count = 3;

            std::list<Player*> playerList;
            GetPlayerListInGrid(playerList, me, 300.0f);
            Trinity::Containers::RandomResizeList(playerList, count);

            if (playerList.empty())
                return;

            for (auto& player : playerList)
            {
                DoCast(player, SpellOrbOfCorruptionVisual, true);

                ObjectGuid const targetGuid = player->GetGUID();
                Position pos = player->GetPosition();
                pos.m_positionX -= 6.0f;
                pos.m_positionY -= 6.0f;
                me->AddDelayedCombat(2000, [this, pos, targetGuid, aiLifetimeGuard = std::weak_ptr<uint8>(_delayedAILifetimeGuard)]()
                {
                    if (aiLifetimeGuard.expired()) return;
                    if (eventPhase == PHASE_1 && me->isInCombat() && me->IsAlive())
                        me->SummonCreature(Data::Creatures::OrbOfCorruption, pos, targetGuid, TEMPSUMMON_TIMED_DESPAWN, 9000);
                });
            }
            break;
        }
        case SpellOrbOfCorrosion:
        {
            if (me->GetMap() && (me->GetMap()->GetSpawnMode() == DIFFICULTY_NORMAL_RAID) || (me->GetMap()->GetSpawnMode() == DIFFICULTY_LFR_RAID))
                count = 2;
            else if (me->GetMap() && (me->GetMap()->GetSpawnMode() == DIFFICULTY_MYTHIC_RAID) || (me->GetMap()->GetSpawnMode() == DIFFICULTY_HEROIC_RAID))
                count = 3;

            std::list<Player*> playerList;
            GetPlayerListInGrid(playerList, me, 300.0f);
            Trinity::Containers::RandomResizeList(playerList, count);

            if (playerList.empty())
                return;

            for (auto& player : playerList)
            {
                ObjectGuid const targetGuid = player->GetGUID();

                DoCast(player, SpellOrbOfCorrosionVisual, true);

                Position pos = player->GetPosition();
                pos.m_positionX -= 6.0f;
                pos.m_positionY -= 6.0f;
                me->AddDelayedCombat(2000, [this, pos, targetGuid, aiLifetimeGuard = std::weak_ptr<uint8>(_delayedAILifetimeGuard)]()
                {
                    if (aiLifetimeGuard.expired()) return;
                    if (eventPhase == PHASE_3 && me->isInCombat() && me->IsAlive())
                        me->SummonCreature(Data::Creatures::OrbOfCorrosion, pos, targetGuid, TEMPSUMMON_TIMED_DESPAWN, 9000);
                });
            }
            break;
        }
        case SpellBilewaterBreath:
        {
            uint8 count = me->GetMap()->GetPlayersCountExceptGMs();

            if (count <= 10)
                count = 2;
            else if (count <= 15)
                count = 3;
            else if (count <= 20)
                count = 4;
            else if (count <= 25)
                count = 5;
            else
                count = 6;

            float dist = 40.0f;
            for (uint8 i = 0; i < count; ++i)
            {
                dist += 11.0f;
                float x, y;
                me->GetNearPoint2D(x, y, dist, me->GetOrientation(), false);
                float z = me->GetHeight(x, y, MAX_HEIGHT, true, MAX_FALL_DISTANCE);
                if (z > INVALID_HEIGHT)
                    me->CastSpell(x, y, z, SpellBilewaterBreathNpc, true);
            }
            break;
        }
        case SpellCorruptedBreath:
        {
            if (!IsHeroicPlusRaid())
                return;

            uint32 countTarget = 0;

            if (IsMythicRaid())
                countTarget = 5;
            else
                countTarget = 3;

            float dist = 30.0f;
            for (uint8 i = 0; i < countTarget; ++i)
            {
                dist += 13.0f;
                float x, y;
                me->GetNearPoint2D(x, y, dist, me->GetOrientation(), false);
                // A missile can land above/below Helya. Walking-position helpers
                // reject those height changes and can return the caster instead.
                float z = me->GetHeight(x, y, MAX_HEIGHT, true, MAX_FALL_DISTANCE);
                if (z > INVALID_HEIGHT)
                    me->CastSpell(x, y, z, SpellCorruptedAxion, true);
            }
            break;
        }
        case SpellOrbOfCorrosionShare:
            DoCast(owner, SpellOrbOfCorrosionDmg, true);
            break;
        }
    }

    void SpellHitTarget(Unit* target, SpellInfo const* spell) override
    {
        switch (spell->Id)
        {
        case SpellBilewaterBreathDmg:
            DoCast(target, SpellBilewaterRedox, true);
            break;
        case SpellCorruptedBreathDmg:
            DoCast(target, SpellDarkHatred, false);
            break;
        }
    }

    void SpellFinishCast(SpellInfo const* spell) override
    {
        switch (spell->Id)
        {
        case SpellFuryOfTheMawAT:
            if (IsHeroicPlusRaid())
            {
                if (!FuryOfTheMawTrash)
                {
                    events.RescheduleEvent(EVENT_BOAT, 500);
                    events.ScheduleEvent(EVENT_SUMMON_SKELETION, 31000);
                    events.ScheduleEvent(EVENT_SUMMON_SKELETION, 41000);
                    FuryOfTheMawTrash = true;
                }
                events.RescheduleEvent(EVENT_FURY_OF_THE_MAW_CLEAN_AT, 3000);
            }
            else if (IsLfrRaid() || IsNormalRaid())
            {
                if (eventPhase == PHASE_3 || eventPhase == PHASE_2)
                {
                    events.RescheduleEvent(EVENT_BOAT, 500);
                    events.ScheduleEvent(EVENT_SUMMON_SKELETION, 31000);
                    events.ScheduleEvent(EVENT_SUMMON_SKELETION, 41000);
                }
            }
            break;
        }
    }

    void DoAction(int32 const action) override
    {
        switch (action)
        {
        case ACTION_1:
            if (eventPhase != PHASE_2 || !me->isInCombat() || instance->GetBossState(Data::BossIDs::HelyaID) != IN_PROGRESS)
                break;

            DoCast(SpellHelyaAltPowerRegen);
            events.RescheduleEvent(EVENT_TORRENT, 2000);
            break;
        case ACTION_2:
            if (instance->GetBossState(Data::BossIDs::GarmID) == DONE)
            {
                Talk(SAY_INTRO_1);
                me->AddDelayedEvent(13000, [=, aiLifetimeGuard = std::weak_ptr<uint8>(_delayedAILifetimeGuard)]() -> void { if (aiLifetimeGuard.expired()) return; Talk(SAY_INTRO_2); });
            }
            break;
        default:
            break;
        }
    }

    void JustSummoned(Creature* sum) override
    {
        summons.Summon(sum);

        switch (sum->GetEntry())
        {
        case Data::Creatures::OrbOfCorruption:
            if (auto target = ObjectAccessor::GetUnit(*sum, sum->GetTargetGUID()))
                sum->CastSpell(target, SpellOrbofCorruptionOnPlayer, true);
            break;
        case Data::Creatures::OrbOfCorrosion:
            if (auto target = ObjectAccessor::GetUnit(*sum, sum->GetTargetGUID()))
                sum->CastSpell(target, SpellOrbofCorrosionOnPlayer, true);
            break;
        case Data::Creatures::NightWatchMariner:
            if (eventPhase == PHASE_3)
                sum->AddAura(SpellRallyOfTheKvaldir, sum);
            break;
        default:
            break;
        }
    }

    uint32 GetData(uint32 type) const override
    {
        if (type == Data::BossIDs::HelyaID)
            return eventPhase;
        return 0;
    }

    void UpdateAI(uint32 diff) override
    {
        if (!UpdateVictim() && me->isInCombat())
            return;

        if (_checkEvadeTimer)
        {
            if (_checkEvadeTimer <= diff)
            {
                _checkEvadeTimer = 1500;

                if (auto victim = me->getVictim())
                {
                    if (me->GetDistance(victim) > 90.0f && eventPhase != PHASE_2)
                        EnterEvadeMode();
                    else if (me->GetDistance(victim) > 140.0f && eventPhase == PHASE_2)
                        EnterEvadeMode();
                }
            }
            else
                _checkEvadeTimer -= diff;
        }

        events.Update(diff);

        if (me->HasUnitState(UNIT_STATE_CASTING))
            return;

        if (uint32 eventId = events.ExecuteEvent())
        {
            switch (eventId)
            {
            case EVENT_TAINT_OF_THE_SEA:
            {
                if (eventPhase == PHASE_1 || eventPhase == PHASE_3)
                {
                    std::list<Player*> targets;
                    for (auto reference : me->getThreatManager().getThreatList())
                        if (Unit* unit = reference->getTarget())
                            if (Player* player = unit->ToPlayer())
                                if (player->IsAlive() && player->IsInWorld() && !player->isGameMaster() && player->GetMap() == me->GetMap())
                                    targets.push_back(player);

                    // The active tank is always one of the targets; pets must not consume a slot.
                    uint32 count = IsMythicRaid() ? 5 : 3;
                    if (Unit* victim = me->getVictim())
                        if (Player* tank = victim->ToPlayer())
                            if (std::find(targets.begin(), targets.end(), tank) != targets.end())
                            {
                                me->AddAura(SpellTaintOfTheSea, tank);
                                targets.remove(tank);
                                --count;
                            }

                    Trinity::Containers::RandomResizeList(targets, count);
                    for (Player* target : targets)
                        me->AddAura(SpellTaintOfTheSea, target);
                    if (eventPhase == PHASE_3)
                        events.RescheduleEvent(EVENT_TAINT_OF_THE_SEA, IsMythicRaid() ? 20000 : 28000);
                    else
                        events.RescheduleEvent(EVENT_TAINT_OF_THE_SEA, IsLfrRaid() ? 17000 : 12100);
                }
                break;
            }
            case EVENT_TENTECLE_STRIKE:
                if (eventPhase == PHASE_1)
                {
                    me->SummonCreature(Data::Creatures::StrikingTentacle, StrikingTentacle[urand(0, 2)], TEMPSUMMON_TIMED_DESPAWN, 9000);

                    if (IsMythicRaid())
                        events.RescheduleEvent(EVENT_TENTECLE_STRIKE, 35000);
                    else
                        events.RescheduleEvent(EVENT_TENTECLE_STRIKE, 30000);
                }
                break;
            case EVENT_ORB_OF_CURRUPTION:
                if (eventPhase == PHASE_1)
                {
                    DoCast(SpellOrbOfCorruption);

                    if (IsMythicRaid())
                        events.RescheduleEvent(EVENT_ORB_OF_CURRUPTION, 23000);
                    else
                        events.RescheduleEvent(EVENT_ORB_OF_CURRUPTION, 26000);
                }
                break;
            case EVENT_ORB_OF_CORROSION:
                if (eventPhase == PHASE_3)
                {
                    Talk(SAY_ORB_OF_CORROSION);
                    DoCast(SpellOrbOfCorrosion);

                    if (IsMythicRaid())
                        events.RescheduleEvent(EVENT_ORB_OF_CORROSION, 13000);
                    else
                        events.RescheduleEvent(EVENT_ORB_OF_CORROSION, 17000);
                }
                break;
            case EVENT_TORRENT:
                if (!me->HasUnitState(UNIT_STATE_CASTING))
                {
                    if (eventPhase == PHASE_2)
                    {
                        if (!me->HasAura(SpellFureOfTheMawLong))
                        {
                            power = me->GetPower(POWER_ALTERNATE);

                            if (power <= 95)
                            {
                                DoCast(SpellTorrent);
                                events.RescheduleEvent(EVENT_TORRENT, 10000);
                            }
                        }
                    }
                }
                break;
            case EVENT_TELEPORT_OUTSIDE:
                me->NearTeleportTo(553.95f, 733.01f, 5.1663f, 4.03013f);
                break;
            case EVENT_TELEPORT_HOME:
                me->NearTeleportTo(524.031f, 699.055f, 5.17631f, 4.29875f);
                break;
            case EVENT_FURY_OF_THE_MAW:
                DoCast(SpellFuryOfTheMawAT);
                events.RescheduleEvent(EVENT_FURY_OF_THE_MAW_CLEAN_AT, 3000);
                break;
            case EVENT_FURY_OF_THE_MAW_CLEAN_AT:
                me->RemoveAreaObject(SpellBilewaterLiquefactionDmg);
                me->RemoveAreaObject(SpellDecay);
                break;
            case EVENT_REANIMATION:
                if (eventPhase == 0)
                {
                    DoCast(SpellReanimation1);
                    DoCast(SpellReanimation2);
                    events.RescheduleEvent(EVENT_REANIMATION, 15000);
                }
                break;
            case EVENT_SUMMON_SKELETION:
                for (uint8 i = 0; i < 10; ++i)
                    me->SummonCreature(Data::Creatures::DecayingMinion, skeletionPos[i], TEMPSUMMON_CORPSE_TIMED_DESPAWN, 5000);
                break;
            case EVENT_BOAT:
                if (eventPhase == PHASE_2)
                {
                    me->SummonCreature(Data::Creatures::KvaldirLongboat, 569.39f, 857.6201f, 0.00213f, 4.433769f, TEMPSUMMON_TIMED_DESPAWN, 5000);
                    me->SummonCreature(Data::Creatures::KvaldirLongboat, 638.672f, 817.6201f, 0.00213f, 3.943812f, TEMPSUMMON_TIMED_DESPAWN, 5000);
                    me->AddDelayedCombat(4000, [=, aiLifetimeGuard = std::weak_ptr<uint8>(_delayedAILifetimeGuard)]() -> void
                    {
                        if (aiLifetimeGuard.expired()) return;
                        me->SummonCreature(Data::Creatures::Grimelord, 458.674f, 639.483f, 7.53757f, 4.433769f, TEMPSUMMON_CORPSE_TIMED_DESPAWN, 5000);
                        me->SummonCreature(Data::Creatures::NightWatchMariner, 516.007f, 614.179f, 5.5823f, 3.943812f, TEMPSUMMON_CORPSE_TIMED_DESPAWN, 5000);
                    });
                    if (IsMythicRaid())
                    {
                        me->SummonCreature(Data::Creatures::HelarjarMistwatcher, 564.366f, 653.4237f, 17.9559f, 2.401197f, TEMPSUMMON_CORPSE_TIMED_DESPAWN, 5000);
                        me->SummonCreature(Data::Creatures::HelarjarMistwatcher, 469.7802f, 703.5213f, 17.96658f, 6.12398f, TEMPSUMMON_CORPSE_TIMED_DESPAWN, 5000);
                    }
                }
                else if (eventPhase == PHASE_3)
                {
                    me->AddDelayedCombat(4000, [=, aiLifetimeGuard = std::weak_ptr<uint8>(_delayedAILifetimeGuard)]() -> void
                    {
                        if (aiLifetimeGuard.expired()) return;
                        me->SummonCreature(Data::Creatures::NightWatchMariner, 516.007f, 614.179f, 5.5823f, 3.943812f, TEMPSUMMON_CORPSE_TIMED_DESPAWN, 5000);
                    });
                    me->SummonCreature(Data::Creatures::KvaldirLongboat, 638.672f, 817.6201f, 0.00213f, 3.943812f, TEMPSUMMON_TIMED_DESPAWN, 5000);
                }
                break;
            }
        }

        if (berserk)
        {
            if (berserk <= diff)
            {
                berserk = 0;
                DoCast(me, SpellBerserk, true);
            }
            else
                berserk -= diff;
        }

        if (AOEdmg)
        {
            if (AOEdmg <= diff)
            {
                if (eventPhase != PHASE_2)
                {
                    if (checkrephase)
                        return;

                    if (auto victim = me->getVictim())
                        if (!me->IsWithinMeleeRange(victim))
                            DoCast(SpellCorrosiveNova);
                }
            }
            else
                AOEdmg -= diff;
        }
        DoMeleeAttackIfReady();
    }
private:
    // Unit-owned queues may outlive this AI object.
    std::shared_ptr<uint8> _delayedAILifetimeGuard = std::make_shared<uint8>(0);
}

